'use client';
import { useCallback, useEffect, useMemo, useState, lazy, Suspense } from 'react';
import { ArrowUpRight, ArrowRight, BookOpen, Braces, Check, ChevronRight, Code2, Download, Flame, FolderOpen, GraduationCap, LayoutGrid, Lightbulb, LockKeyhole, Menu, Moon, Play, Search, Settings as SettingsIcon, Sun, Target, Trophy, X, Zap, CheckCircle2, Circle, ArrowUp, ArrowDown, ExternalLink, PanelsTopLeft, Monitor, FileCode2 } from 'lucide-react';
import { lessons, modules } from '../../lib/academy/curriculum';
import { canOpen, complete, finishReview, dayKey, initialProgress, loadProgress, parseProgress, recordAttempt, saveProgress, streak, xp } from '../../lib/academy/progress';
import { checkProject, pageNames, referenceProject, starterProject } from '../../lib/academy/project';
import { download, zipBytes } from '../../lib/academy/zip';
import type { Progress, Lesson, CodeFiles } from '../../lib/academy/types';
import type { CheckResult } from '../../lib/academy/runtime';
import Editor, { highlight } from './Editor';
import Cloud from './Cloud';
import { georgianError } from '../../lib/academy/locale-errors';
const Workspace=lazy(()=>import('./Workspace'));
const Diagnostics=lazy(()=>import('./Diagnostics'));
type Update=(fn:(p:Progress)=>Progress)=>void;
const navItems=[{to:'home',label:"სასწავლო სივრცე",icon:LayoutGrid},{to:'path',label:"კურსის გზა",icon:GraduationCap},{to:'practice',label:"პრაქტიკა",icon:Braces},{to:'workshop',label:"ჩემი ვებსაიტი",icon:FolderOpen},{to:'reference',label:"ცნობარი",icon:BookOpen}];
function go(to:string){window.location.hash=to;window.scrollTo({top:0});}
function Badge({children}:{children:React.ReactNode}){return <span className="badge">{children}</span>}
function Code({children}:{children:string}){return <pre className="example-code"><code dangerouslySetInnerHTML={{__html:highlight(children)}}/></pre>}
function Mark({small=false}:{small?:boolean}){return <span className={'brand-mark '+(small?'small':'')} aria-hidden="true"><span/><span/><span/></span>}
function ModuleIcon({index}:{index:number}){const icons=[Code2,PanelsTopLeft,Braces,LayoutGrid,Monitor,FileCode2,Play,ArrowUpRight];const Icon=icons[index];return <span className={'module-icon color-'+modules[index].color}><Icon size={22}/></span>}
export default function App(){
 const [progress,setProgress]=useState<Progress|null>(null);const [route,setRoute]=useState('home');const [menu,setMenu]=useState(false);const [notice,setNotice]=useState('');const [storageError,setStorageError]=useState('');const [loaded,setLoaded]=useState(false);
 useEffect(()=>{let mounted=true;queueMicrotask(()=>{if(!mounted)return;let p:Progress;try{p=loadProgress();}catch{p=initialProgress();setStorageError("შენახული ასლი ვერ წავიკითხეთ. ბრაუზერის თავდაპირველი მონაცემები შენარჩუნებულია. ახალი სამუშაოს შენახვამდე პარამეტრებში ჩამოტვირთე ან შეასწორე ასლი.");}setProgress(p);setLoaded(true);});const sync=()=>{setRoute(location.hash.slice(1)||'home');setMenu(false);};queueMicrotask(sync);window.addEventListener('hashchange',sync);return()=>{mounted=false;window.removeEventListener('hashchange',sync);};},[]);
 useEffect(()=>{if(!progress||!loaded||storageError)return;try{saveProgress(progress);}catch{queueMicrotask(()=>setStorageError("ბრაუზერმა ცვლილება ვერ შეინახა. სამუშაოს დასაცავად პარამეტრებიდან პროგრესის ასლი ჩამოტვირთე."));}},[progress,loaded,storageError]);
 useEffect(()=>{if(!progress)return;const mq=window.matchMedia('(prefers-color-scheme: dark)');const apply=()=>{document.documentElement.dataset.theme=progress.profile.theme==='system'?(mq.matches?'dark':'light'):progress.profile.theme;document.documentElement.style.fontSize=progress.profile.fontSize+'px';document.documentElement.dataset.motion=progress.profile.reducedMotion?'reduce':'auto';};apply();mq.addEventListener('change',apply);return()=>mq.removeEventListener('change',apply);},[progress]);
 const update:Update=useCallback(fn=>setProgress(p=>p?{...fn(p),updated:new Date().toISOString()}:p),[]);
 const notify=useCallback((s:string)=>setNotice(s),[]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),5500);return()=>clearTimeout(t);},[notice]);
 if(!progress)return <div className="loading"><Mark/><p>შენი სასწავლო სივრცე იხსნება…</p></div>;
 const p=progress;const lessonId=Number(route.split('/')[1]);const practice=route.startsWith('review/');const lesson=(route.startsWith('lesson/')||practice)?lessons.find(l=>l.id===lessonId):null;const active=lesson?'path':route;
 return <div className="app-shell"><a className="skip-link" href="#main-content" onClick={e=>{e.preventDefault();document.querySelector<HTMLElement>('#main-content')?.focus();}}>მთავარ შინაარსზე გადასვლა</a><aside className={'sidebar '+(menu?'open':'')}><a href="#home" className="brand"><Mark/><span>firstlight<span className="brand-period">.</span></span></a><div className="sidebar-course"><span className="eyebrow">შენი შემდეგი თავი</span><strong>ვებდეველოპმენტი</strong><span>ინტერესიდან ცოდნამდე.</span></div><nav aria-label="მთავარი ნავიგაცია">{navItems.map(n=><a href={'#'+n.to} className={active===n.to?'active':''} key={n.to} aria-current={active===n.to?'page':undefined}><n.icon size={19}/>{n.label}{n.to==='practice'&&p.reviews.some(r=>new Date(r.due)<=new Date())&&<span className="nav-dot"/>}{n.to==='workshop'&&<span className="nav-new">5 გვერდი</span>}</a>)}</nav><div className="sidebar-bottom"><div className="course-mini"><div><span>შენი კურსი</span><strong>{p.completed.length}/48</strong></div><div className="progress-track"><span style={{width:p.completed.length/48*100+'%'}}/></div><p>ერთი ახალი უნარი ყოველ ნაბიჯზე.</p></div><a href="#settings" className={active==='settings'?'active':''}><SettingsIcon size={19}/> პარამეტრები და პროგრესი</a><a className="profile" href="#settings"><span className="avatar">{p.profile.name?p.profile.name[0].toUpperCase():'შ'}</span><span><strong>{p.profile.name||"შენი სასწავლო სივრცე"}</strong><small>სწავლობ სტუმრის რეჟიმში</small></span><ChevronRight size={15}/></a></div></aside>{menu&&<button className="sidebar-scrim" aria-label="ნავიგაციის დახურვა" onClick={()=>setMenu(false)}/>}
 <div className="app-main"><header className="topbar"><div><button className="icon-button mobile-menu" aria-label="ნავიგაციის გახსნა" onClick={()=>setMenu(!menu)}><Menu size={20}/></button><span className="topbar-location">ვებდეველოპმენტი <ChevronRight size={13}/><strong>{lesson?"გაკვეთილის სამუშაო სივრცე":navItems.find(n=>n.to===route)?.label??(route==='settings'?"შენი პარამეტრები":"კეთილი იყოს შენი მობრძანება")}</strong></span></div><div className="topbar-right"><span className="top-stat"><Flame size={17}/><strong>{streak(p)}</strong><span>დღე ზედიზედ</span></span><span className="top-stat xp"><Zap size={17}/><strong>{xp(p)}</strong><span>XP</span></span><button className="icon-button theme-toggle" aria-label="ფერების რეჟიმის შეცვლა" title="ფერების რეჟიმის შეცვლა" onClick={()=>update(p=>({...p,profile:{...p.profile,theme:document.documentElement.dataset.theme==='dark'?'light':'dark'}}))}>{p.profile.theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button><span className="avatar small">{p.profile.name?p.profile.name[0].toUpperCase():'შ'}</span></div></header>
 {storageError&&<div className="storage-warning" role="alert">{storageError}<button onClick={()=>{setStorageError('');notify("შენახვა ჩართულია. ასლის ჩამოტვირთვა პარამეტრებიდან შეგიძლია.");}}>ამ სესიაში შენახვის ჩართვა</button><a href="#settings">პარამეტრების გახსნა</a></div>}
 <main id="main-content" tabIndex={-1} className={lesson?'main-content lesson-main':'main-content'}>{lesson?<LessonView key={route} lesson={lesson} practice={practice} p={p} update={update} notify={notify}/>:route==='path'?<CoursePath p={p}/>:route==='onboarding'?<Onboarding p={p} update={update}/>:route==='workshop'?<Workshop p={p} update={update} notify={notify}/>:route==='practice'?<Practice p={p}/>:route==='reference'?<Reference/>:route==='settings'?<Settings p={p} update={update} notify={notify}/>:route==='welcome'?<Welcome p={p}/>:route==='diagnostics'?<Suspense fallback={<p>შემოწმება იტვირთება…</p>}><Diagnostics/></Suspense>:<Home p={p}/>}</main><footer className="app-footer"><span>Firstlight · როცა ყველაფერი გასაგები ხდება.</span><a href="#welcome">კურსის შესახებ <ArrowUpRight size={12}/></a></footer></div>{notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}<button aria-label="შეტყობინების დახურვა" onClick={()=>setNotice('')}><X size={15}/></button></div>}</div>;
}
function Home({p}:{p:Progress}){const next=lessons.find(l=>!p.completed.includes(l.id));const current=next?.module??7;const today=dayKey(new Date(),p.profile.timezone);const minutes=(p.daily[today]??[]).reduce((n,id)=>n+lessons[id-1].minutes,0);const pct=Math.min(100,minutes/p.profile.minutes*100);const due=p.reviews.filter(r=>new Date(r.due)<=new Date());const start=()=>go(p.profile.onboarded?'lesson/'+(next?.id??48):'onboarding');
 return <><div className="page-heading"><div><p className="eyebrow">კარგი დღეა ახალი ცოდნისთვის</p><h1>{p.profile.name?`კეთილი დაბრუნება, ${p.profile.name}.`:"პატარა წინსვლა ყოველდღე."}</h1><p>შენი იდეები შექმნად ღირს. საჭირო ცოდნით დავიწყოთ.</p></div><Badge><span className="live-dot"/> HTML · CSS · JavaScript</Badge></div><div className="home-grid"><div className="home-primary"><section className="hero-card"><div className="hero-copy"><span className="eyebrow">პირველი ტეგიდან საკუთარ საიტამდე</span><h2>პატარა ნაბიჯები.<br/>ნამდვილი საიტები.</h2><p>ისწავლე კეთებით, იპოვე შენი ტემპი და შექმენი რაღაც საკუთარი.</p><button className="button light" onClick={start}>{p.completed.length?"გააგრძელე სწავლა":"დაწერე პირველი ხაზი"}<ArrowRight size={17}/></button><span className="hero-meta">გამოცდილება არ გჭირდება. ინტერესიც საკმარისია.</span></div><div className="code-art" aria-hidden="true"><div className="art-caption">ვები შენი შემოქმედების სივრცეა.</div><div className="art-browser"><div className="art-browser-top"><i/><i/><i/><span>your-first-idea.html</span></div><div className="art-browser-code"><span>&lt;main&gt;</span><span>  &lt;h1&gt;<b>გამარჯობა, სამყაროვ.</b>&lt;/h1&gt;</span><span>  &lt;p&gt;შენ შექმენი.&lt;/p&gt;</span><span>&lt;/main&gt;</span></div></div><div className="art-result"><span className="art-asterisk">✳</span><span>გამარჯობა, სამყაროვ.<small>შენ შექმენი.</small></span><ArrowUpRight size={26}/></div><div className="art-bottom"><span>&lt;/&gt;</span><span>იდეა → კოდი → შედეგი</span></div></div></section>
 <section className="next-section"><div className="section-heading"><h2>{next?"შენი შემდეგი ნაბიჯი":"საფუძველი უკვე მყარია"}</h2><a href="#path">კურსის გზის ნახვა <ArrowRight size={14}/></a></div><article className="next-card"><ModuleIcon index={current}/><div className="next-card-body"><p className="eyebrow">მოდული {String(current+1).padStart(2,'0')} <span>·</span> {modules[current].title.toUpperCase()}</p><h3>{next?.title??"გაიმეორე ნასწავლი"}</h3><p>{next?next.objective: "გაიმყარე ცოდნა სხვადასხვა სავარჯიშოთი და საკუთარი პროექტებით."}</p><div className="lesson-meta"><span><BookOpen size={13}/>{next?.minutes??7} წუთის გაკვეთილი</span><span><Code2 size={13}/>3 პრაქტიკული სავარჯიშო</span><span className="violet-text">+30 XP</span></div></div><button className="circle-button" aria-label="შემდეგი გაკვეთილის დაწყება" onClick={start}><ArrowRight size={21}/></button></article></section>
 <section><div className="section-heading"><h2>ნაბიჯ-ნაბიჯ წინ.</h2><a href="#path">რვავე მოდული <ArrowRight size={14}/></a></div><div className="module-overview">{modules.slice(0,3).map((m,i)=>{const count=p.completed.filter(n=>lessons[n-1].module===i).length;const isCurrent=current===i;return <a href={'#path'} className={'module-card '+(isCurrent?'current':'')} key={m.title}><div className="module-card-top"><ModuleIcon index={i}/><span>{count===6?<Check size={16}/>:isCurrent?"მიმდინარეობს":String(i+1).padStart(2,'0')}</span></div><h3>{m.title}</h3><p>{m.short}</p><div className="progress-track"><span style={{width:count/6*100+'%'}}/></div><small>{count} / 6 გაკვეთილი <ChevronRight size={13}/></small></a>})}</div></section>
 <section className="workshop-promo"><div className="tiny-website" aria-hidden="true"><div><span>north®</span><i>↗</i></div><strong>შენი იდეები.<br/>სივრცე ზრდისთვის.</strong><span className="tiny-website-line"/><span className="tiny-website-bottom">მთავარი &nbsp; ჩვენ &nbsp; სერვისები &nbsp; ნამუშევრები &nbsp; კონტაქტი</span></div><div><p className="eyebrow">ერთი კურსი. ხელშესახები შედეგი.</p><h3>ხუთი გვერდი. მთლიანად შენი.</h3><p>სწავლისას ააწყვე სტუდიის ნამდვილი საიტი. კოდი შენ გრჩება — შეცვალე და თან წაიღე.</p><a href="#workshop">გახსენი სამუშაო სივრცე <ArrowUpRight size={15}/></a></div></section></div>
 <aside className="home-secondary"><section className="daily-card"><div className="section-heading"><h2>შენი ყოველდღიური ტემპი</h2><Target size={19}/></div><div className="daily-ring"><svg viewBox="0 0 140 140" aria-label={`${minutes} of ${p.profile.minutes} სასწავლო წუთი მიახლოებით`}><circle cx="70" cy="70" r="58"/><circle className="ring-progress" cx="70" cy="70" r="58" strokeDasharray="364.4" strokeDashoffset={364.4*(1-pct/100)}/></svg><div><strong>{minutes}<span> / {p.profile.minutes}</span></strong><small>სასწავლო წუთი</small></div></div><p>{minutes?"კარგად მუშაობ. ყოველი დასრულებული გაკვეთილი ითვლება.":"მცირე დრო. ცოდნა, რომელიც გრჩება."}</p><div className="week-dots">{Array.from({length:7},(_,i)=>{const now=new Date();now.setDate(now.getDate()-(6-i));const key=dayKey(now,p.profile.timezone);return <div key={key}><span>{['კვ','ორ','სა','ოთ','ხუ','პა','შა'][new Date(key+'T12:00Z').getUTCDay()]}</span><i className={(p.daily[key]?.length?'done ':'')+(key===today?'today':'')}>{p.daily[key]?.length?<Check size={13}/>:<span/>}</i></div>})}</div><a href="#settings">შეცვალე დღიური მიზანი <ChevronRight size={12}/></a><small className="footnote">წუთები დასრულებული გაკვეთილების სავარაუდო დროა.</small></section>
 <section className="review-card"><span className="review-icon"><Braces size={22}/></span><h3>ცოტა პრაქტიკა<br/>ცოდნას ამყარებს.</h3><p>{due.length?`${due.length} თემა გამეორებას ელოდება. მოკლე გახსენება ცოდნის გამყარებაში დაგეხმარება.`:"გამეორება ახალ ცოდნას ამყარებს. სასწავლო მასალასთან ერთად შენი გამეორების სიაც გაიზრდება."}</p><a className="outline-button" href="#practice">{due.length?"გაიმეორე თემები":"ნახე სავარჯიშოები"}<ArrowRight size={15}/></a></section><section className="milestone-card"><div className="section-heading"><h2>შენი პირველი ეტაპი</h2><Trophy size={18}/></div><div className="milestone-symbol"><span><Code2 size={32}/></span></div><h3>{p.completed.length>=6?"პირველი გვერდი მზადაა.":"გამარჯობა, ვებო."}</h3><p>{p.completed.length>=6?"პირველი მოდული დაასრულე. ცარიელი გვერდი უკვე საწყისი წერტილია.":"დაასრულე პირველი მოდული და ცარიელი გვერდი ვების საკუთარ პატარა კუთხედ აქციე."}</p><div className="progress-track"><span style={{width:p.completed.filter(n=>n<=6).length/6*100+'%'}}/></div><small>{p.completed.filter(n=>n<=6).length} / 6 გაკვეთილი დასრულებულია</small></section><p className="sidebar-quote">„რაღაცის გასაგებად<br/>მისი შექმნა საუკეთესო გზაა.“<span>ჩვენი მიდგომა სწავლასთან</span></p></aside></div></>;
}
function CoursePath({p}:{p:Progress}){const [expanded,setExpanded]=useState<number[]>([Math.min(7,Math.floor(p.completed.length/6))]);return <><div className="page-heading"><div><p className="eyebrow">გზა ინტერესიდან ცოდნამდე</p><h1>ყოველი ნაბიჯი ახალ ცოდნას გაძლევს.</h1><p>48 გაკვეთილი. 8 თავი. შენით შექმნილი ვებსაიტი.</p></div><Badge>{p.completed.length} / 48 დასრულებულია</Badge></div><div className="path-layout"><div className="course-path">{modules.map((m,i)=>{const count=p.completed.filter(n=>lessons[n-1].module===i).length;const open=expanded.includes(i);return <section className={'path-module '+(count===6?'finished':'')} key={m.title}><button className="path-module-heading" onClick={()=>setExpanded(x=>x.includes(i)?x.filter(n=>n!==i):[...x,i])} aria-expanded={open}><ModuleIcon index={i}/><span><small>მოდული {String(i+1).padStart(2,'0')} · {lessons.filter(l=>l.module===i).reduce((n,l)=>n+l.minutes,0)} წთ</small><strong>{m.title}</strong><span>{m.description}</span></span><div className="module-count">{count===6?<CheckCircle2 size={21}/>:<span>{count}/6</span>}<ChevronRight size={17} className={open?'rotated':''}/></div></button>{open&&<div className="path-lessons">{lessons.filter(l=>l.module===i).map(l=>{const done=p.completed.includes(l.id);const unlocked=canOpen(l.id,p);return <button key={l.id} disabled={!unlocked} className={'path-lesson '+(done?'done':unlocked?'available':'locked')} onClick={()=>go(p.profile.onboarded?'lesson/'+l.id:'onboarding')}><span className="path-node">{done?<Check size={18}/>:unlocked?<Play size={16} fill="currentColor"/>:<LockKeyhole size={15}/>}</span><span><strong>{l.title}</strong><small>{l.minutes} წთ · {l.id%6===0?"მოდულის შემაჯამებელი":"3 სავარჯიშო"}{!unlocked?" · გასახსნელად დაასრულე წინა გაკვეთილი":''}</small></span>{done?<span className="review-label">გაიმეორე</span>:unlocked?<ArrowRight size={18}/>:null}</button>})}</div>}</section>})}</div><aside className="path-aside"><span className="eyebrow">შენი მომავალი პროექტი</span><div className="mini-project"><PanelsTopLeft size={35}/><h3>სტუდია „ნორთი“</h3><p>სტუდიის ხუთგვერდიანი საიტი, რომელიც ეკრანს ერგება. შენი კოდი. შენი იდეები.</p></div><ul>{["გასაგები და მიმზიდველი მთავარი გვერდი","ამბავი, რომლის მოყოლაც ღირს","სერვისების სასარგებლო აღწერები","პროექტების გალერეა ფილტრებით","საკონტაქტო ფორმა ზუსტი პასუხებით"].map(t=><li key={t}><Check size={14}/>{t}</li>)}</ul><a href="#workshop" className="outline-button">ნახე შენი პროექტი <ArrowUpRight size={15}/></a><p className="footnote">დასრულებული გაკვეთილები ხელმისაწვდომი რჩება. ცდების რაოდენობა შეუზღუდავია.</p></aside></div></>}
function Onboarding({p,update}:{p:Progress;update:Update}){const [step,setStep]=useState(0);const [name,setName]=useState(p.profile.name);const [experience,setExperience]=useState(p.profile.experience);const [goal,setGoal]=useState(p.profile.goal);const [minutes,setMinutes]=useState(p.profile.minutes);const [placement,setPlacement]=useState(false);const [answer,setAnswer]=useState<number|null>(null);
 return <div className="onboarding"><span className="eyebrow">დაიწყე შენზე მორგებულად</span><div className="onboarding-steps">{[0,1,2].map(n=><span className={n<=step?'active':''} key={n}/>)}</div><h1>{["ჯერ ცოტა შენ შესახებ.","რისი სწავლა გსურს?","გამოყავი ცოტა დრო სწავლისთვის."][step]}</h1><p>{["საფუძვლებიდან დავიწყებთ და ცოდნას პრაქტიკაში გამოვიყენებთ.","სასარგებლო ცოდნის მიღებას ნებისმიერი მიზეზი უხდება.","აირჩიე შენს ცხოვრებაზე მორგებული ტემპი. მისი შეცვლა ნებისმიერ დროს შეგიძლია."][step]}</p>{step===0?<><label className="field-label">რა სახელით მოგმართოთ? <span>(არასავალდებულო)</span><input value={name} maxLength={60} onChange={e=>setName(e.target.value)} placeholder="შენი სახელი"/></label><h3>ადრე კოდი დაგიწერია?</h3><div className="choice-list">{[['brand-new',"სრულიად დამწყები ვარ","დავიწყოთ იმით, რა არის ვებგვერდი."],['some-html',"ცოტა HTML მიცდია","რამდენიმე ტეგი ვიცი, მაგრამ მყარი საფუძველი მჭირდება."],['some-code',"კოდი ადრეც დამიწერია","მინდა ცოდნა ერთმანეთს დავუკავშირო."]].map(([v,t,d])=><button className={experience===v?'selected':''} key={v} onClick={()=>setExperience(v)}><Circle size={19}/><span><strong>{t}</strong><small>{d}</small></span>{experience===v&&<Check size={18}/>}</button>)}</div></>:step===1?<div className="choice-list">{[['personal',"საკუთარი საიტის შექმნა","პორტფოლიო, მცირე ბიზნესი ან საკუთარი იდეა."],['career',"ახალი მიმართულების აღმოჩენა","პრაქტიკული უნარების განვითარება და ახალი შესაძლებლობები."],['curiosity',"ვების მუშაობის გაგება","ინტერესის დაკმაყოფილება და ხელშესახები შედეგის შექმნა."]].map(([v,t,d])=><button className={goal===v?'selected':''} key={v} onClick={()=>setGoal(v)}><Lightbulb size={20}/><span><strong>{t}</strong><small>{d}</small></span>{goal===v&&<Check size={18}/>}</button>)}</div>:<><div className="goal-options">{[5,10,20].map(n=><button className={minutes===n?'selected':''} key={n} onClick={()=>setMinutes(n)}><strong>{n}<small> წთ</small></strong><span>{n===5?"მსუბუქი დასაწყისი":n===10?"სტაბილური ტემპი":"მეტი დრო სწავლისთვის"}</span></button>)}</div><p className="footnote">მიზანი დასრულებული გაკვეთილების სავარაუდო დროს ითვლის. უკუთვლა და შეზღუდვები არ არის.</p><button className="text-button" onClick={()=>setPlacement(!placement)}>{placement?"საწყისი ცოდნის შემოწმების დახურვა":"HTML უკვე იცი? სურვილისამებრ, საწყისი ცოდნა შეამოწმე."}</button>{placement&&<div className="placement"><h3>რომელი ბმული აკავშირებს მეზობელ გვერდებს?</h3>{['<a href="about.html">შესახებ</a>','<link>about.html</link>','<button src="about.html">შესახებ</button>'].map((x,i)=><button key={x} className={'quiz-choice '+(answer===i?'selected':'')} onClick={()=>setAnswer(i)}><code>{x}</code></button>)}{answer!==null&&<p className={answer===0?'success':'error'}>{answer===0?"ნამდვილი ბმული ამოიცანი. საფუძვლები მოკლედ გაიმეორე — შემდეგი გაკვეთილები მათ ეყრდნობა.":"a ელემენტი href-ით სხვა გვერდზე გადადის. ამას საწყისი ნაბიჯებიდან ვისწავლით."}</p>}</div>}</> }<div className="onboarding-actions">{step>0&&<button className="outline-button" onClick={()=>setStep(step-1)}>უკან</button>}<button className="button" onClick={()=>{if(step<2)setStep(step+1);else{update(p=>({...p,profile:{...p.profile,name:name.trim(),experience,goal,minutes,onboarded:true}}));go('lesson/1');}}}>{step===2?"დავწეროთ კოდი":"გაგრძელება"}<ArrowRight size={16}/></button></div></div>;
}
function LessonView({lesson:l,practice,p,update,notify}:{lesson:Lesson;practice:boolean;p:Progress;update:Update;notify:(s:string)=>void}){
 const [part,setPart]=useState(0);const [answer,setAnswer]=useState<number|null>(null);const [quizPass,setQuizPass]=useState(false);const [feedback,setFeedback]=useState('');const [lines,setLines]=useState(l.order.lines.map((_,i)=>i).reverse());const [orderPass,setOrderPass]=useState(false);const [orderMessage,setOrderMessage]=useState('');const [hints,setHints]=useState(0);const [solution,setSolution]=useState(false);const [manual,setManual]=useState(false);const [codePass,setCodePass]=useState(false);const [ended,setEnded]=useState(false);const [confirmReset,setConfirmReset]=useState(false);const key=String(l.id)+(practice?':practice':'');const files=p.drafts[key]??l.starter;
 const onCode=useCallback((files:CodeFiles)=>{setCodePass(false);update(p=>({...p,drafts:{...p.drafts,[key]:files}}));},[key,update]);
 const onResults=useCallback((results:CheckResult[])=>{if(!results.length){setCodePass(false);return;}const correct=results.filter(r=>!r.manual).every(r=>r.pass)&&results.some(r=>!r.manual);setCodePass(correct);update(p=>recordAttempt(p,l.id,"კოდი",correct));},[l.id,update]);
 if(!practice&&!canOpen(l.id,p))return <div className="empty-state"><LockKeyhole size={40}/><h1>ჯერ საფუძვლები გავიმყაროთ.</h1><p>ჯერ დაასრულე გაკვეთილი {l.id-1} და შემდეგ გახსენი ეს გაკვეთილი. ყოველი ნაბიჯი წინას ეყრდნობა.</p><a className="button" href="#path">კურსის გზაზე დაბრუნება</a></div>;
 if(practice&&!p.attempts.some(a=>a.lesson===l.id)&&!p.completed.includes(l.id))return <div className="empty-state"><BookOpen size={40}/><h1>ჯერ ეს თემა ისწავლე.</h1><p>პრაქტიკა უკვე ნაცად თემებს შეგახსენებს.</p><a className="button" href="#path">კურსის დათვალიერება</a></div>;
 if(ended)return <div className="lesson-finished"><span className="finished-check"><Check size={42}/></span><p className="eyebrow">{practice?"სასარგებლო გამეორება":"კიდევ ერთი ნაბიჯი გადადგმულია"}</p><h1>{practice?"კიდევ უფრო თავდაჯერებულად.":p.completed.length===48?"შეძელი. შექმნა გააგრძელე.":"ნახე, უკვე რა შეგიძლია."}</h1><p>{l.recap}</p><div className="completion-recap"><span><Zap size={19}/>{practice?"პრაქტიკა ჩაიწერა":"+30 XP · მხოლოდ პირველად დასრულებისას"}</span><span><CheckCircle2 size={19}/>3 სავარჯიშო დასრულებულია</span></div>{l.id%6===0&&<div className="module-achievement"><Trophy size={25}/><p><strong>{modules[l.module].title} დასრულებულია.</strong><br/>დროა, ეს ცოდნა საკუთარ საიტში გამოიყენო.</p></div>}<div className="finished-actions"><a href="#workshop" className="outline-button">სცადე შენს პროექტში <ArrowUpRight size={16}/></a><button className="button" onClick={()=>go(practice?'practice':l.id<48?'lesson/'+(l.id+1):'path')}>{practice?"პრაქტიკაზე დაბრუნება":l.id<48?"შემდეგი გაკვეთილი":"ნახე შენი პროგრესი"}<ArrowRight size={16}/></button></div></div>;
 return <><div className="lesson-heading"><a href={practice?'#practice':'#path'} className="back-link">← {practice?"პრაქტიკა":"კურსის გზა"}</a><div className="lesson-heading-row"><div><p className="eyebrow">მოდული {l.module+1} · გაკვეთილი {(l.id-1)%6+1} / 6 · {l.minutes} წთ</p><h1>{l.title}</h1></div><Badge>{practice?"გამეორების რეჟიმი":p.completed.includes(l.id)?"დასრულებულია · გაიმეორე":'+30 XP'}</Badge></div><div className="lesson-stepper">{["გაიგე იდეა","ააწყვე ნაწილები","აამუშავე"].map((t,i)=><button key={t} className={(part===i?'active ':'')+((i===0&&quizPass||i===1&&orderPass||i===2&&codePass)?'done':'')} onClick={()=>setPart(i)}><span>{i===0&&quizPass||i===1&&orderPass||i===2&&codePass?<Check size={13}/>:i+1}</span>{t}</button>)}</div></div>
 {part===0?<div className="lesson-reading"><div className="reading-main"><p className="eyebrow">მთავარი იდეა</p><h2>გავიგოთ, როგორ მუშაობს.</h2><p className="lesson-explanation">{l.explanation}</p><h3>პატარა მაგალითი</h3><Code>{l.example}</Code><p className="annotation"><Lightbulb size={17}/>{l.annotation}</p><div className="knowledge-check"><p className="eyebrow">{l.quiz.type==='predict'?"გამოიცანი შედეგი":l.quiz.type==='fill'?"იპოვე გამოტოვებული ნაწილი":"მოკლე შემოწმება"}</p><h3>{l.quiz.question}</h3>{l.quiz.choices.map((c,i)=><button key={c} className={'quiz-choice '+(answer===i?'selected ':'')+(quizPass&&i===answer?'correct':'')} onClick={()=>{setAnswer(i);setFeedback('');}}><span className="choice-letter">{String.fromCharCode(65+i)}</span><span>{c}</span>{quizPass&&i===answer&&<Check size={17}/>}</button>)}{feedback&&<p role="status" className={'feedback '+(quizPass?'success':'error')}>{feedback}</p>}<button className="button" disabled={answer===null} onClick={()=>{const correct=answer===l.quiz.correct;setQuizPass(correct);setFeedback(l.quiz.explanations[answer!]);update(p=>recordAttempt(p,l.id,'quiz',correct));}}>პასუხის შემოწმება <Check size={16}/></button></div><div className="lesson-next"><span>{quizPass?"იდეა უკვე გასაგები ხდება.":"შეამოწმე პასუხი, შემდეგ კოდის ნაწილები დაალაგე."}</span><button className="button" onClick={()=>setPart(1)}>ააწყვე ნაწილები <ArrowRight size={16}/></button></div></div><aside className="learning-note"><Target size={23}/><h3>შენი მიზანი</h3><p>{l.objective}</p><hr/><span className="eyebrow">ამ გაკვეთილამდე</span><p>{l.id===1?"წინასწარი გამოცდილება არ გჭირდება. ბრაუზერი და ეს ჩანართები საკმარისია.":`მოკლე გახსენება: ${lessons[l.id-2].recap}`}</p><a href={l.id===1?'#reference':'#lesson/'+(l.id-1)}>გაიმეორე საფუძველი <ArrowUpRight size={13}/></a><hr/><span className="eyebrow">შენს საკუთარ საიტში</span><p>{l.connection}</p></aside></div>:part===1?<div className="ordering-lesson"><p className="eyebrow">დაფიქრდი სტრუქტურაზე</p><h2>{l.order.prompt}</h2><p>ნაწილები ისრებით გადაადგილე. ღილაკები კლავიატურითაც და შეხებითაც მუშაობს.</p><div className="ordering-items">{lines.map((n,i)=><div className="order-row" key={n}><span>{i+1}</span><code>{l.order.lines[n]}</code><div><button className="icon-button" aria-label={`გადაადგილება: ხაზი ${i+1} ზემოთ`} disabled={!i} onClick={()=>{setOrderPass(false);setOrderMessage('');setLines(a=>{const b=[...a];[b[i-1],b[i]]=[b[i],b[i-1]];return b;});}}><ArrowUp size={16}/></button><button className="icon-button" aria-label={`გადაადგილება: ხაზი ${i+1} ქვემოთ`} disabled={i===lines.length-1} onClick={()=>{setOrderPass(false);setOrderMessage('');setLines(a=>{const b=[...a];[b[i],b[i+1]]=[b[i+1],b[i]];return b;});}}><ArrowDown size={16}/></button></div></div>)}</div>{orderMessage&&<p className={'feedback '+(orderPass?'success':'error')} role="status">{orderMessage}</p>}<div className="lesson-next"><button className="outline-button" onClick={()=>{const correct=lines.every((n,i)=>n===i);setOrderPass(correct);setOrderMessage(correct?"სტრუქტურა სწორია. ახლა საკუთარი კოდი დაწერე.":"ჯერ არა. დაფიქრდი, რა უნდა განისაზღვროს მანამდე, სანამ შემდეგი ნაწილი მას გამოიყენებს.");update(p=>recordAttempt(p,l.id,'order',correct));}}>თანმიმდევრობის შემოწმება <Check size={16}/></button><button className="button" onClick={()=>setPart(2)}>აამუშავე <ArrowRight size={16}/></button></div></div>:<><div className="coding-brief"><div><p className="eyebrow">შენი ჯერია · {l.id%6===0?"მოდულის შემაჯამებელი":"დაწერე, გაუშვი, დახვეწე"}</p><h2>{l.language==='js'&&[31,46].includes(l.id)?"იპოვე შეცდომა და შეასწორე.":l.language==='css'?"მიეცი იდეას ფორმა.":"შექმენი შენი ვერსია."}</h2><p>{l.task}</p></div><span className="save-indicator"><span className="live-dot"/>ავტომატურად ინახება ამ ბრაუზერში</span></div><Suspense fallback={<div className="loading-panel">კოდის სამუშაო სივრცე იხსნება…</div>}><Workspace files={files} onChange={onCode} checks={l.checks} onResults={onResults} instructions={l.task} onReset={()=>setConfirmReset(true)}/></Suspense>{confirmReset&&<div className="inline-confirm"><p>დავაბრუნოთ სავარჯიშოს საწყისი კოდი? შენი საიტის სამუშაო ფაილები შენარჩუნდება.</p><button className="outline-button" onClick={()=>setConfirmReset(false)}>ჩემი კოდის შენარჩუნება</button><button className="button" onClick={()=>{onCode(l.starter);setConfirmReset(false);}}>საწყის კოდზე დაბრუნება</button></div>}<div className="lesson-support"><div><button className="outline-button" onClick={()=>setHints(Math.min(2,hints+1))}><Lightbulb size={16}/>{hints<2?"მინიშნება "+(hints+1):"ორივე მინიშნება გახსნილია"}</button><button className="text-button" onClick={()=>setSolution(!solution)}>{solution?"ამოხსნის დახურვა":"ამოხსნის მაგალითის ნახვა"}</button></div><span className="footnote">ცდები შეუზღუდავია. ყოველი მცდელობა რაღაცას გასწავლის.</span></div>{hints>0&&<div className="hint-panel">{l.hints.slice(0,hints).map((h,i)=><p key={h}><strong>მინიშნება {i+1}.</strong> {h}</p>)}</div>}{solution&&<div className="solution-panel"><h3>ამოხსნის ერთ-ერთი გზა</h3><Code>{l.solution[l.language]}</Code><p>{l.annotation} {l.recap}</p><p className="footnote">ამოხსნის წაკითხვა დავალებას ვერ ცვლის. დაუბრუნდი შენს კოდს, შეცვალე და გაუშვი.</p></div>}{l.checks.some(c=>c.manual)&&<label className="manual-ack"><input type="checkbox" checked={manual} onChange={e=>setManual(e.target.checked)}/><span>შემოწმებებთან მოცემული ხელით გასავლელი მითითებებიც შევასრულე.</span></label>}<div className="lesson-complete-bar"><div><strong>{quizPass&&orderPass&&codePass?"მზად ხარ შემდეგი ნაბიჯისთვის.":"რამდენიმე ნაწილი დასასრულებელია."}</strong><span>{[quizPass?"✓ ცოდნის შემოწმება":"ცოდნის შემოწმება",orderPass?"✓ კოდის თანმიმდევრობა":"კოდის თანმიმდევრობა",codePass?"✓ კოდის დავალება":"კოდის დავალება"].join(' · ')}</span></div><button className="button" disabled={!quizPass||!orderPass||!codePass||(l.checks.some(c=>c.manual)&&!manual)} onClick={()=>{update(p=>practice||p.completed.includes(l.id)?finishReview(p,l.id):complete(p,l.id));setEnded(true);notify(practice?"პრაქტიკა შენახულია. სასარგებლო ცოდნა გაიმეორე.":p.completed.includes(l.id)?"გაკვეთილი გაიმეორე. გამოცდილების ქულები სწორად ითვლება.":"გაკვეთილი დასრულებულია. მიიღე 30 XP.");}}>{practice?"პრაქტიკის დასრულება":"გაკვეთილის დასრულება"}<ArrowRight size={16}/></button></div></> }</>;
}
function Workshop({p,update,notify}:{p:Progress;update:Update;notify:(s:string)=>void}){
 const [file,setFile]=useState('index.html');const [previewPage,setPreviewPage]=useState('index.html');const [view,setView]=useState('preview');const [reference,setReference]=useState(false);const [results,setResults]=useState<ReturnType<typeof checkProject>|null>(null);const [reset,setReset]=useState(false);const [manual,setManual]=useState<Record<string,boolean>>({});
 const starter=useMemo(()=>starterProject(),[]);const completed=useMemo(()=>referenceProject(),[]);const project=Object.keys(p.project).length?p.project:starter;const files=reference?completed:project;
 const preview=useMemo(()=>{let html=files[previewPage]??files['index.html'];for(const [path,content]of Object.entries(files)){if(path.endsWith('.svg'))html=html.replaceAll(path,'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(content));}return {html,css:files['css/styles.css']??'',js:files['js/main.js']??''};},[files,previewPage]);
 const edit=(value:string)=>{if(reference)return;setResults(null);update(p=>({...p,project:{...project,[file]:value}}));};
 const check=()=>{const r=checkProject(files,s=>new DOMParser().parseFromString(s,'text/html'));setResults(r);if(!reference)update(p=>({...p,project:{...project},milestones:r.filter(x=>x.checks.every(c=>c.pass)).map(x=>x.id)}));notify("სტრუქტურის შემოწმება დასრულდა. მოქმედებები გადახედვაშიც გამოცადე.");};
 const exportProject=()=>{download(reference?'north-studio-reference.zip':'my-north-studio.zip',zipBytes(files) as BlobPart);if(!reference)update(p=>({...p,project:{...project}}));notify("ZIP ჩამოტვირთულია. ამოარქივე, საქაღალდეები ერთად დატოვე და index.html გახსენი.");};
 return <><div className="page-heading"><div><p className="eyebrow">შენი შესაქმნელი საიტი</p><h1>შენი იდეები მუშაობაშია.</h1><p>სტუდიის ხუთგვერდიანი საიტი. ეტაპობრივად და მთლიანად შენით შექმნილი.</p></div><button className="button" onClick={exportProject}><Download size={16}/>საიტის ჩამოტვირთვა</button></div><div className="workshop-intro"><span className="project-badge"><PanelsTopLeft size={21}/></span><div><strong>სტუდია „ნორთი“ <Badge>{reference?"დასრულებული ნიმუში":"შენი სამუშაო პროექტი"}</Badge></strong><p>{reference?"დაათვალიერე დასრულებული ნიმუში. შენი ფაილები შენარჩუნებულია.":"ფაილები წერისას ინახება. გაკვეთილის მონახაზები ცალკეა და მათი გახსნა ამ პროექტს არ ცვლის."}</p></div><button className="outline-button" onClick={()=>{setReference(!reference);setResults(null);}}>{reference?"ჩემს საიტზე დაბრუნება":"ნიმუშის დათვალიერება"}<ExternalLink size={14}/></button></div><div className="workshop-layout"><aside className="file-tree"><p className="eyebrow">პროექტის ფაილები</p>{Object.keys(files).map(path=><button key={path} className={file===path?'active':''} onClick={()=>{setFile(path);setView('editor');if(pageNames.includes(path))setPreviewPage(path);}}><FileCode2 size={15}/><span>{path}</span></button>)}<span className="file-save-status"><CheckCircle2 size={13}/>{reference?"ნიმუში მხოლოდ წაკითხვისთვისაა":"ავტომატურად ინახება ამ ბრაუზერში"}</span></aside><section className="project-workarea"><div className="project-tabs"><div><button className={view==='editor'?'active':''} onClick={()=>setView('editor')}><Code2 size={15}/>რედაქტორი</button><button className={view==='preview'?'active':''} onClick={()=>setView('preview')}><Monitor size={15}/>გადახედვა და გაშვება</button><button className={view==='milestones'?'active':''} onClick={()=>setView('milestones')}><CheckCircle2 size={15}/>ეტაპები</button></div><span>{file}</span></div>{view==='editor'?<><div className="project-editor-title"><span>{file}</span><span>{reference?"მხოლოდ წაკითხვა":"შენი კოდი"}</span></div><Editor key={file} label={"პროექტის ფაილის რედაქტირება: "+file} value={files[file]??''} onChange={edit} readOnly={reference}/><div className="project-editor-footer"><span>შეცვალე ფაილი, შემდეგ აირჩიე „გადახედვა და გაშვება“.</span><button className="small-button" onClick={()=>setView('preview')}>გვერდის გადახედვა <ArrowRight size={14}/></button></div></>:view==='preview'?<><div className="preview-page-select"><label>გვერდი <select value={previewPage} onChange={e=>{setPreviewPage(e.target.value);setFile(e.target.value);}}>{pageNames.map(f=><option key={f}>{f}</option>)}</select></label><span>მოქმედებების ჩასართავად აირჩიე „კოდის გაშვება“.</span></div><Suspense fallback={<p>გადახედვა იტვირთება…</p>}><Workspace key={previewPage+(reference?'-ref':'')} files={preview} onChange={f=>{if(reference)return;setResults(null);update(p=>({...p,project:{...project,[previewPage]:f.html,'css/styles.css':f.css,'js/main.js':f.js}}));}} onNavigate={path=>{if(pageNames.includes(path))setPreviewPage(path);else notify("ეს ბმული გადახედვის ფარგლებს სცდება. ფაილში მისი მისამართი შეამოწმე.");}} readOnly={reference}/></Suspense></>:<div className="milestones"><div className="section-heading"><div><h2>გამართული სტრუქტურა. ბევრი შესაძლებლობა.</h2><p>კურსის გავლისას ამ ეტაპებს მიჰყევი.</p></div><button className="button small" onClick={check}>ფაილების შემოწმება <Check size={15}/></button></div>{[{name:"ხუთი დაკავშირებული გვერდი",text:"მოდულები 1–2 · ყველა გვერდზე შექმენი მთავარი სათაური, სემანტიკური სექციები, საერთო ნავიგაცია და ქვედა ნაწილი.",hint:"დაიწყე index.html-ით, შემდეგ სტრუქტურა სტუდიის, სერვისების, პროექტებისა და კონტაქტის გვერდებს მოარგე."},{name:"საერთო ვიზუალური საფუძველი",text:"მოდულები 3–4 · განსაზღვრე ფერები, დაშორებები, ტექსტი, ღილაკები, კონტეინერები და ბარათების განლაგება.",hint:"საერთო წესები css/styles.css-ში შეინახე. გამოიყენე კონტეინერი, Flexbox სათავე და Grid ბარათები."},{name:"სხვადასხვა ეკრანისთვის მზად",text:"მოდული 5 · დაიწყე ერთი სვეტით, ფართო ეკრანზე გააფართოვე განლაგება და შეინარჩუნე კლავიატურის მხარდაჭერა.",hint:"გაიარე 360px, 768px და 1440px სიგანეები. შეამოწმე ჰორიზონტალური გადაცდენა და მოჭრილი ტექსტი."},{name:"ინტერაქტიულობის საფუძვლები",text:"მოდულები 6–7 · დაამატე ადაპტირებადი მენიუ, კატეგორიის ფილტრები, შენახული რეჟიმი და ვალიდაციის ზუსტი პასუხები.",hint:"გამოიყენე js/main.js და ელემენტების არსებობა შეამოწმე, რათა სკრიპტმა ხუთივე გვერდზე იმუშაოს."},{name:"საბოლოო დეტალები",text:"მოდული 8 · გადაამოწმე ტექსტი, მეტამონაცემები, სურათების აღწერები, ფოკუსი და ექსპორტის ინსტრუქცია.",hint:"საქაღალდის გაზიარებამდე გახსენი ჩამოტვირთული index.html და ხუთივე გვერდი გაიარე."}].map((m,i)=>{const result=results?.[i];return <article key={m.name} className="milestone-item"><span>{result?.checks.every(c=>c.pass)?<Check size={18}/>:String(i+1).padStart(2,'0')}</span><div><h3>{m.name}</h3><p>{m.text}</p><details><summary>მინიშნება გჭირდება?</summary><p>{m.hint}</p></details>{result&&<div className="milestone-checks" aria-live="polite">{result.checks.map(c=><p className={c.pass?'success':'error'} key={c.label}>{c.pass?<Check size={14}/>:<X size={14}/>} {c.label}</p>)}</div>}<label className="manual-ack"><input type="checkbox" checked={!!manual[m.name]} onChange={e=>setManual({...manual,[m.name]:e.target.checked})}/>ეს ეტაპი გადახედვაში ხელითაც შევამოწმე.</label></div></article>})}<div className="note-box">ფაილების შემოწმება სტრუქტურას ადასტურებს. ფილტრი, რეჟიმი და ფორმა „გადახედვა და გაშვებით“ გამოცადე, შემდეგ კლავიატურა და სამივე ეკრანის ზომა შეამოწმე.</div></div>}</section></div><div className="workshop-footer"><p><Lightbulb size={16}/>ჩამოტვირთული საიტი ჩვეულებრივ HTML-ს, CSS-სა და JavaScript-ს იყენებს. აგების პროგრამები არ სჭირდება.</p><button className="text-button" onClick={()=>setReset(true)}>პროექტის საწყისზე დაბრუნება</button></div>{reset&&<div className="inline-confirm"><p>სამუშაო ფაილები საწყისი ვერსიით შევცვალოთ? ამ ვერსიის შესანარჩუნებლად ჯერ ZIP ჩამოტვირთე.</p><button className="outline-button" onClick={()=>setReset(false)}>ჩემი ფაილების შენარჩუნება</button><button className="button" onClick={()=>{update(p=>({...p,project:starter,milestones:[]}));setReset(false);setResults(null);notify("საწყისი პროექტი აღდგენილია.");}}>პროექტის განულება</button></div>}</>;
}
function Practice({p}:{p:Progress}){const practiced=[...new Set([...p.completed,...p.attempts.map(a=>a.lesson)])];const due=p.reviews.filter(r=>new Date(r.due)<=new Date());const [filter,setFilter]=useState('due');const shown=filter==='due'?due.map(r=>r.lesson):practiced;
 return <><div className="page-heading"><div><p className="eyebrow">აქციე ცოდნა ჩვევად</p><h1>მეტი პრაქტიკა. უფრო მყარი ცოდნა.</h1><p>დაუბრუნდი უკვე ნაცად თემებს. ყოველი მცდელობა წინსვლის შესაძლებლობაა.</p></div><Badge><Braces size={14}/>{due.length} თემა გასამეორებელია</Badge></div><div className="practice-banner"><Braces size={34}/><div><h2>{due.length?"რამდენიმე თემა გამეორებისთვის მზადაა.":"შენი გამეორების კოლექცია ივსება."}</h2><p>შეცდომიანი თემები აქ მაშინვე ბრუნდება. წარმატებული გამეორების შემდეგ შუალედი იზრდება: 2, 4, 8 დღემდე და ასე შემდეგ, მაქსიმუმ 30 დღემდე.</p></div></div><div className="segmented"><button className={filter==='due'?'active':''} onClick={()=>setFilter('due')}>გასამეორებელი <span>{due.length}</span></button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>ყველა ნაცადი თემა <span>{practiced.length}</span></button></div>{shown.length?<div className="practice-grid">{shown.map(id=>{const l=lessons[id-1];const r=p.reviews.find(r=>r.lesson===id);return <a href={'#review/'+id} className="practice-item" key={id}><ModuleIcon index={l.module}/><span className="eyebrow">{modules[l.module].title}</span><h3>{l.title}</h3><p>{l.recap}</p><div><span>{r?.successes??0} ბოლო წარმატებული შემოწმება</span><ArrowUpRight size={17}/></div></a>})}</div>:<div className="empty-state"><BookOpen size={36}/><h2>{filter==='due'?"ცოტაოდენი თავისუფალი დრო.":"შენი პირველი ცოდნა აქ იწყება."}</h2><p>{filter==='due'?"ჯერ გასამეორებელი არაფერია. გააგრძელე კურსი ან აირჩიე „ყველა ნაცადი თემა“.":"სცადე გაკვეთილი და გავლილი თემები აქ გამოჩნდება."}</p><a className="button" href="#path">გააგრძელე სწავლა <ArrowRight size={16}/></a></div>}<div className="note-box"><Lightbulb size={17}/><p>გამეორების მონახაზები ცალკე ინახება და გაკვეთილის კოდს არ ცვლის. პრაქტიკა დამატებით პირველი დასრულების ქულებს არ გასცემს.</p></div></>;
}
