function Reference(){const [query,setQuery]=useState('');const [topic,setTopic]=useState("ყველა");const [active,setActive]=useState<(typeof references)[0]|null>(null);const [scratch,setScratch]=useState<CodeFiles|null>(null);const shown=references.filter(r=>(topic==="ყველა"||r.topic===topic)&&(r.name+' '+r.description+' '+r.code).toLowerCase().includes(query.toLowerCase()));return <><div className="page-heading"><div><p className="eyebrow">სწრაფი დახმარება სწავლისას</p><h1>შენი ვებცნობარი.</h1><p>მოკლე ახსნა. სასარგებლო მაგალითები. როცა გახსენება დაგჭირდება.</p></div><Badge>{references.length} პრაქტიკული ჩანაწერი</Badge></div><div className="reference-controls"><label className="search-field"><Search size={18}/><input aria-label="ცნობარში ძიება" value={query} onChange={e=>setQuery(e.target.value)} placeholder="მოძებნე „Flexbox“, „ფორმები“ ან „ფუნქციები“…"/></label><div className="segmented">{["ყველა",'HTML','CSS','JavaScript'].map(t=><button className={topic===t?'active':''} key={t} onClick={()=>setTopic(t)}>{t}</button>)}</div></div>{active?<section className="reference-playground"><button className="text-button" onClick={()=>{setActive(null);setScratch(null);}}>← ცნობარზე დაბრუნება</button><h2>{active.name}</h2><p>{active.description}</p>{scratch&&<Suspense fallback={<p>საცდელი სივრცე იხსნება…</p>}><Workspace files={scratch} onChange={setScratch}/></Suspense>}<p className="footnote">ეს დროებითი საცდელი კოდია. შენახული გაკვეთილები და პროექტი ცალკეა.</p></section>:shown.length?<div className="reference-grid">{shown.map(r=><article className="reference-card" key={r.name}><span className={'reference-topic '+r.topic.toLowerCase()}>{r.topic}</span><h3>{r.name}</h3><p>{r.description}</p><Code>{r.code}</Code><button className="text-button" onClick={()=>{setActive(r);setScratch({html:r.topic==='HTML'?r.code:'<main><h1>სტუდია ნორთი</h1><p class="intro">სივრცე იდეებისთვის.</p><nav><a href="#">მთავარი</a><a href="#">შესახებ</a></nav><section class="cards"><article class="card" data-category="web">ვებპროექტი</article><article class="card" data-category="print">ბეჭდური პროექტი</article><article class="card" data-category="web">კიდევ ერთი პროექტი</article></section><button>სცადე</button><form><label for="email">ელფოსტა</label><input id="email" type="email" required><button>შეამოწმე</button></form></main>',css:r.topic==='CSS'?r.code:'',js:r.topic==='JavaScript'?r.code:''});}}>მაგალითის გამოცდა <Play size={13}/></button></article>)}</div>:<div className="empty-state"><Search size={30}/><h2>შესაბამისი ჩანაწერი ვერ მოიძებნა.</h2><p>სცადე სხვა სიტყვა ან თემა შეცვალე.</p></div>}</>}
function Settings({p,update,notify}:{p:Progress;update:Update;notify:(s:string)=>void}){const [reset,setReset]=useState('');const [confirm,setConfirm]=useState(false);const [error,setError]=useState('');const [pending,setPending]=useState<Progress|null>(null);
 const setProfile=(key:string,value:unknown)=>update(p=>({...p,profile:{...p.profile,[key]:value}}));
 return <><div className="page-heading"><div><p className="eyebrow">მოირგე სასწავლო სივრცე</p><h1>სწავლა შენს ტემპში.</h1><p>შენი პარამეტრები, შენი პროგრესი, შენი ტემპი.</p></div></div><div className="settings-layout"><section className="settings-card"><h2>ყოველდღიური პარამეტრები</h2><label className="field-label">შენი სახელი<input value={p.profile.name} maxLength={60} placeholder="შენი სახელი" onChange={e=>setProfile('name',e.target.value)}/></label><label className="field-label">დღიური მიზანი<select value={p.profile.minutes} onChange={e=>setProfile('minutes',+e.target.value)}>{[5,10,20].map(n=><option value={n} key={n}>{n} წუთი · {n===5?'მსუბუქი':n===10?'სტაბილური':'ინტენსიური'}</option>)}</select></label><label className="field-label">სწავლის დროის სარტყელი<select value={p.profile.timezone} onChange={e=>setProfile('timezone',e.target.value)}>{[...new Set([p.profile.timezone,Intl.DateTimeFormat().resolvedOptions().timeZone,'UTC','Asia/Tbilisi','Europe/London','America/New_York','America/Los_Angeles','Asia/Tokyo','Australia/Sydney'])].map(z=><option key={z}>{z}</option>)}</select></label><p className="footnote">უწყვეტი სწავლა ამ სარტყლის კალენდარული დღეებით ითვლება. ძველი აქტივობა ჩაწერილ დღეს ინარჩუნებს.</p><label className="field-label">ფერების რეჟიმი<select value={p.profile.theme} onChange={e=>setProfile('theme',e.target.value)}><option value="light">თბილი ღია</option><option value="dark">მშვიდი მუქი</option><option value="system">მოწყობილობის მიხედვით</option></select></label><label className="field-label">ტექსტის ზომა<select value={p.profile.fontSize} onChange={e=>setProfile('fontSize',+e.target.value)}><option value="16">ჩვეულებრივი</option><option value="18">კომფორტული</option><option value="20">დიდი</option></select></label><label className="toggle-label"><input type="checkbox" checked={p.profile.reducedMotion} onChange={e=>setProfile('reducedMotion',e.target.checked)}/><span><strong>მოძრაობის შემცირება</strong><small>მოწყობილობის მოძრაობის პარამეტრიც გათვალისწინებულია.</small></span></label></section><div><section className="settings-card"><h2>შენი პროგრესი ერთი შეხედვით</h2><div className="settings-stats"><div><strong>{p.completed.length}</strong><span>დასრულებული გაკვეთილი</span></div><div><strong>{xp(p)}</strong><span>მიღებული XP</span></div><div><strong>{streak(p)}</strong><span>დღე ზედიზედ</span></div></div><p><strong>დონე {Math.floor(xp(p)/180)+1}</strong> · თითო დონეს 180 XP სჭირდება. გაკვეთილის პირველად დასრულება 30 XP-ს გაძლევს. გამეორება ცოდნის შენარჩუნებაში გეხმარება.</p><h3>მოდულების მიღწევები</h3><div className="achievement-list">{modules.map((m,i)=>{const done=lessons.filter(l=>l.module===i).every(l=>p.completed.includes(l.id));return <span title={done?"მიღებულია":"მისაღებად ექვსივე გაკვეთილი დაასრულე"} className={done?'earned':''} key={m.title}><Trophy size={15}/>{m.title}{done&&<Check size={13}/>}</span>})}</div></section><section className="settings-card"><h2>შეინახე შენი ნამუშევრის ასლი</h2><p>კოდი და პროგრესი ამ ბრაუზერში ინახება. სხვა მოწყობილობაზე გადასატანად ან ბრაუზერის გასუფთავებამდე ასლი ჩამოტვირთე.</p><div className="button-row"><button className="outline-button" onClick={()=>download('firstlight-progress.json',JSON.stringify(p,null,2),'application/json')}><Download size={15}/>პროგრესის ჩამოტვირთვა</button><label className="outline-button file-upload">ასლის შემოტანა<input type="file" accept="application/json,.json" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>3_000_000)throw new Error("გამოიყენე 3 მბ-ზე ნაკლები ზომის ასლი.");setPending(parseProgress(await f.text()));setError('');}catch(err){setError(georgianError((err as Error).message));}e.target.value='';}}/></label></div>{error&&<p className="error" role="alert">{error}</p>}{pending&&<div className="inline-confirm"><p>ეს ასლი შეიცავს {pending.completed.length} დასრულებულ გაკვეთილს და {Object.keys(pending.project).length} პროექტის ფაილს. შემოტანა ბრაუზერის მიმდინარე პროგრესს ჩაანაცვლებს. საჭიროების შემთხვევაში ჯერ ახლანდელი ასლი ჩამოტვირთე.</p><button className="outline-button" onClick={()=>setPending(null)}>გაუქმება</button><button className="button" onClick={()=>{update(()=>pending);setPending(null);notify("ასლი შემოტანილია. სასწავლო სივრცე მზადაა.");}}>ამ ასლის შემოტანა</button></div>}</section><Cloud p={p} update={update} notify={notify}/><section className="settings-card danger-zone"><h2>ახალი დასაწყისი</h2><p>განულება ამ ბრაუზერიდან კურსის პროგრესს, სავარჯიშოების მონახაზებსა და საიტის ფაილებს შლის. შესანარჩუნებლად ჯერ ასლი ჩამოტვირთე.</p>{!confirm?<button className="outline-button danger" onClick={()=>setConfirm(true)}>სასწავლო სივრცის განულება</button>:<><label className="field-label">დასადასტურებლად ჩაწერე RESET<input value={reset} onChange={e=>setReset(e.target.value)}/></label><div className="button-row"><button className="outline-button" onClick={()=>setConfirm(false)}>ჩემი ნამუშევრის შენარჩუნება</button><button className="button danger" disabled={reset!=='RESET'} onClick={()=>{update(()=>initialProgress());setConfirm(false);setReset('');notify("სასწავლო სივრცე განულებულია.");}}>ყველაფრის განულება</button></div></>}</section><a className="text-button" href="#diagnostics">სასწავლო გარემოს შემოწმება <ArrowUpRight size={13}/></a></div></div></>;
}
function Welcome({p}:{p:Progress}){return <div className="welcome-page"><p className="eyebrow">FIRSTLIGHT · დაიწყე პრაქტიკით</p><h1>ვებსაიტის შექმნა<br/>შენც შეგიძლია.</h1><p className="lede">არ არის აუცილებელი იცოდე, საიდან დაიწყო. ამაში ჩვენ დაგეხმარებით. ისწავლე HTML, CSS და JavaScript პატარა ნაბიჯებით, რომლებიც ნამდვილ საიტად გაერთიანდება.</p><button className="button" onClick={()=>go(p.profile.onboarded?'path':'onboarding')}>სწავლის დაწყება <ArrowRight size={16}/></button><a className="text-button" href="#path">სასწავლო პროგრამის ნახვა</a><div className="welcome-features">{[['01',"გაიგე ერთი პატარა იდეა","მარტივად დაწერილი ახსნა და მაგალითები, რომელთა შეცვლაც შეგიძლია."],['02',"სცადე შენით","დაწერე კოდი, გაუშვი იზოლირებულ გარემოში და მიიღე სასარგებლო უკუკავშირი."],['03',"შექმენი რაღაც საკუთარი","გააერთიანე ცოდნა სტუდიის ხუთგვერდიან საიტში."]].map(([n,t,d])=><article key={n}><span>{n}</span><h2>{t}</h2><p>{d}</p></article>)}</div><section className="welcome-demo"><div><p className="eyebrow">სცადე ახლავე</p><h2>პირველი ხაზი იმაზე ახლოსაა, ვიდრე გგონია.</h2><p>შეცვალე ეს სათაური და აირჩიე „კოდის გაშვება“. შენ ნამდვილი ვებგვერდი შეცვალე.</p></div><Suspense fallback={<p>შენი პირველი ცდის სივრცე იხსნება…</p>}><WelcomeEditor/></Suspense></section><div className="welcome-details"><div><strong>48</strong><span>სრულფასოვანი გაკვეთილი</span></div><div><strong>144</strong><span>ძირითადი სავარჯიშო</span></div><div><strong>5</strong><span>გვერდი შენს საიტში</span></div><div><strong>შენია</strong><span>კოდის ყოველი ხაზი</span></div></div><p className="footnote">სტუმრის რეჟიმში სწავლა უფასოა. არ გჭირდება AI გასაღები, გადახდა ან ცდების ლიმიტი. ღრუბლოვანი ანგარიში არასავალდებულოა და გამართვას საჭიროებს.</p></div>}
function WelcomeEditor(){const [files,setFiles]=useState({html:'<h1>გამარჯობა, ვებო!</h1>\n<p>ჩემი პირველი იდეა აქ იწყება.</p>',css:'h1 { color: #6d4aff; }',js:''});return <Workspace files={files} onChange={setFiles}/>}
